CREATE VIEW public.v_purchase_logistics AS
 SELECT po.order_id AS "Order Number",
    po.order_date AS "Date",
    s.supplier_name AS "Supplier Name",
    (((e.first_name)::text || ' '::text) || (e.last_name)::text) AS "Ordered By"
   FROM ((public.purchase_orders po
     JOIN public.suppliers s ON ((po.supplier_id = s.supplier_id)))
     JOIN public.employee e ON ((po.employee_id = e.e_id)));


